      "secret_fear": "害怕被沈浅遗忘，害怕无法改变悲剧命运"
    }
  ],
  "supporting_characters": [
    {
      "name": "老陈",
      "function": "助力",
      "identity": "公寓的老邮差",
      "description": "负责投递信件的老人，知道一些关于公寓的秘密，暗中帮助沈浅"
    }
